"use client";

import { useMemo, useState } from "react";
import { ArrowUpRight, RefreshCcw, Trash2, X } from "lucide-react";
import { RoleRouteGuard } from "@/compartido/components/role/role-route-guard";
import { useAuthUser } from "@/compartido/hooks/use-auth-user";
import { useVacancyTheme } from "@/compartido/theme/use-vacancy-theme";
import { AdminDashboardShell } from "@/frontend/admin/components/system/admin-dashboard-shell";
import {
  AdminUserFormFields,
  buildUpdatePayload,
  createAdminUserFormFromUser,
  getConfirmationName,
  type AdminUserFormState,
} from "@/frontend/admin/components/system/admin-user-form";
import { useAdminUsers } from "@/frontend/admin/hooks/use-admin-users";
import type { AdminTrashedUserPreview, AdminUserPreview } from "@/compartido/types/admin";
import {
  AdminGhostButton,
  AdminPill,
  AdminPrimaryButton,
  AdminSimpleTable,
  AdminSurface,
  AdminToolbarInput,
} from "@/frontend/admin/components/system/admin-dashboard-kit";

function UserEditorModal({
  isDark,
  user,
  form,
  deleteJustification,
  deleteConfirmStep,
  saving,
  deleting,
  onClose,
  onFormChange,
  onDeleteJustificationChange,
  onDeleteConfirmStepChange,
  onSave,
  onDelete,
}: {
  isDark: boolean;
  user: AdminUserPreview;
  form: AdminUserFormState;
  deleteJustification: string;
  deleteConfirmStep: 0 | 1 | 2;
  saving: boolean;
  deleting: boolean;
  onClose: () => void;
  onFormChange: (next: AdminUserFormState) => void;
  onDeleteJustificationChange: (value: string) => void;
  onDeleteConfirmStepChange: (value: 0 | 1 | 2) => void;
  onSave: () => void;
  onDelete: () => void;
}) {
  const confirmationName = getConfirmationName(user);
  const justificationCharacters = deleteJustification.trim().length;
  const canStartDelete = justificationCharacters >= 10;
  const inputClass = isDark
    ? "w-full rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm text-white outline-none placeholder:text-slate-500"
    : "w-full rounded-2xl border border-slate-300 bg-white px-4 py-3 text-sm text-slate-900 outline-none placeholder:text-slate-400";

  return (
    <div className="fixed inset-0 z-[220] flex items-center justify-center bg-slate-950/70 px-4 py-6" onClick={onClose}>
      <div
        className={isDark ? "max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-3xl border border-white/8 bg-[#0b1020] p-6" : "max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-3xl border border-slate-200 bg-white p-6"}
        onClick={(event) => event.stopPropagation()}
      >
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className={isDark ? "text-xs font-semibold uppercase tracking-[0.2em] text-slate-400" : "text-xs font-semibold uppercase tracking-[0.2em] text-slate-500"}>
              Usuario
            </p>
            <h2 className={isDark ? "mt-2 text-2xl font-semibold text-white" : "mt-2 text-2xl font-semibold text-slate-950"}>
              {confirmationName}
            </h2>
            <p className={isDark ? "mt-2 text-sm text-slate-400" : "mt-2 text-sm text-slate-600"}>
              {user.id} · {user.role}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className={isDark ? "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-slate-100" : "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700"}
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="mt-6">
          <AdminUserFormFields isDark={isDark} form={form} onChange={onFormChange} includePasswordHint />
        </div>

        <div className="mt-6 flex flex-wrap justify-end gap-3">
          <AdminGhostButton isDark={isDark} onClick={onClose}>
            Cancelar
          </AdminGhostButton>
          <AdminPrimaryButton disabled={saving} onClick={onSave}>
            {saving ? "Guardando..." : "Guardar cambios"}
          </AdminPrimaryButton>
        </div>

        <div className={isDark ? "mt-8 rounded-3xl border border-rose-400/20 bg-rose-500/10 p-5" : "mt-8 rounded-3xl border border-rose-200 bg-rose-50 p-5"}>
          <div className="flex items-start gap-3">
            <Trash2 className={isDark ? "mt-1 h-4 w-4 text-rose-200" : "mt-1 h-4 w-4 text-rose-700"} />
            <div className="flex-1">
              <p className={isDark ? "font-semibold text-rose-100" : "font-semibold text-rose-900"}>Eliminar usuario</p>
              <p className={isDark ? "mt-2 text-sm text-rose-100/80" : "mt-2 text-sm text-rose-800"}>
                La cuenta se moverá a una papelera recuperable por 15 días. Escribe una justificación de mínimo 10 caracteres.
              </p>
              <textarea
                value={deleteJustification}
                onChange={(event) => {
                  onDeleteJustificationChange(event.target.value);
                  onDeleteConfirmStepChange(0);
                }}
                placeholder={`Motivo para mover ${confirmationName} a la papelera`}
                className={`${inputClass} mt-4 min-h-28`}
              />
              <p className={isDark ? "mt-2 text-xs text-rose-100/70" : "mt-2 text-xs text-rose-700"}>
                {justificationCharacters}/10 caracteres mínimos.
              </p>
              {deleteConfirmStep === 0 ? (
                <button
                  type="button"
                  disabled={deleting || !canStartDelete}
                  onClick={() => onDeleteConfirmStepChange(1)}
                  className="mt-4 inline-flex items-center gap-2 rounded-2xl bg-rose-600 px-4 py-2.5 text-sm font-medium text-white transition hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  <Trash2 className="h-4 w-4" />
                  Mover a papelera
                </button>
              ) : null}
              {deleteConfirmStep === 1 ? (
                <div className={isDark ? "mt-4 rounded-2xl border border-rose-300/20 bg-rose-950/30 p-4" : "mt-4 rounded-2xl border border-rose-200 bg-white p-4"}>
                  <p className={isDark ? "text-sm font-semibold text-rose-100" : "text-sm font-semibold text-rose-900"}>¿Estás seguro?</p>
                  <button
                    type="button"
                    disabled={deleting}
                    onClick={() => onDeleteConfirmStepChange(2)}
                    className="mt-3 inline-flex items-center gap-2 rounded-2xl bg-rose-600 px-4 py-2.5 text-sm font-medium text-white transition hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    Sí, estoy seguro
                  </button>
                </div>
              ) : null}
              {deleteConfirmStep === 2 ? (
                <div className={isDark ? "mt-4 rounded-2xl border border-rose-300/20 bg-rose-950/30 p-4" : "mt-4 rounded-2xl border border-rose-200 bg-white p-4"}>
                  <p className={isDark ? "text-sm font-semibold text-rose-100" : "text-sm font-semibold text-rose-900"}>
                    Confirma otra vez para mover esta cuenta a la papelera.
                  </p>
                  <button
                    type="button"
                    disabled={deleting}
                    onClick={onDelete}
                    className="mt-3 inline-flex items-center gap-2 rounded-2xl bg-rose-700 px-4 py-2.5 text-sm font-medium text-white transition hover:bg-rose-800 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    <Trash2 className="h-4 w-4" />
                    {deleting ? "Moviendo..." : "Confirmar y enviar a papelera"}
                  </button>
                </div>
              ) : null}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function TrashedUsersTable({
  isDark,
  trashedUsers,
  deleting,
  onRecover,
  onPurge,
}: {
  isDark: boolean;
  trashedUsers: AdminTrashedUserPreview[];
  deleting: boolean;
  onRecover: (trash: AdminTrashedUserPreview) => void;
  onPurge: (trash: AdminTrashedUserPreview) => void;
}) {
  if (trashedUsers.length === 0) {
    return null;
  }

  return (
    <AdminSurface isDark={isDark} className="scroll-mt-24" id="papelera">
      <div className="mb-4">
        <h2 className={isDark ? "text-lg font-semibold text-white" : "text-lg font-semibold text-slate-950"}>Papelera de usuarios</h2>
        <p className={isDark ? "mt-1 text-sm text-slate-400" : "mt-1 text-sm text-slate-600"}>
          Cuentas archivadas con historial durante 15 días.
        </p>
      </div>
      <AdminSimpleTable isDark={isDark}>
        <table className="w-full min-w-[820px] text-sm">
          <thead className={isDark ? "border-b border-white/8 bg-white/[0.03] text-slate-400" : "border-b border-slate-200 bg-slate-50 text-slate-500"}>
            <tr>
              <th className="px-4 py-3 text-left font-medium">Usuario</th>
              <th className="px-4 py-3 text-left font-medium">Email</th>
              <th className="px-4 py-3 text-left font-medium">Recuperable hasta</th>
              <th className="px-4 py-3 text-left font-medium">Acciones</th>
            </tr>
          </thead>
          <tbody>
            {trashedUsers.map((trash) => (
              <tr key={trash.id} className={isDark ? "border-b border-white/6 last:border-b-0" : "border-b border-slate-100 last:border-b-0"}>
                <td className="px-4 py-4 align-top">
                  <p className={isDark ? "font-medium text-white" : "font-medium text-slate-950"}>{trash.displayName}</p>
                  <p className={isDark ? "mt-1 text-xs text-slate-500" : "mt-1 text-xs text-slate-500"}>{trash.userId} · {trash.role}</p>
                  <p className={isDark ? "mt-2 line-clamp-2 text-xs text-slate-400" : "mt-2 line-clamp-2 text-xs text-slate-600"}>{trash.justification}</p>
                </td>
                <td className="px-4 py-4 align-top">{trash.originalEmail}</td>
                <td className="px-4 py-4 align-top">{new Date(trash.restoreUntil).toLocaleString("es-CO")}</td>
                <td className="px-4 py-4 align-top">
                  <div className="flex flex-wrap gap-2">
                    <AdminGhostButton isDark={isDark} disabled={deleting} onClick={() => onRecover(trash)}>
                      Recuperar
                    </AdminGhostButton>
                    <button
                      type="button"
                      disabled={deleting}
                      onClick={() => onPurge(trash)}
                      className="inline-flex items-center gap-2 rounded-2xl bg-rose-600 px-3 py-2 text-xs font-semibold text-white transition hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      <Trash2 className="h-4 w-4" />
                      Eliminar del todo
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </AdminSimpleTable>
    </AdminSurface>
  );
}

export default function AdminUsersPage() {
  const { isDark, toggleTheme } = useVacancyTheme();
  const { authUser } = useAuthUser();
  const enabled = authUser?.role === "admin";
  const { users, trashedUsers, isLoading, lastUpdatedAt, refreshUsers, updateAdminUser, deleteAdminUser } = useAdminUsers(enabled, 60_000);
  const [query, setQuery] = useState("");
  const [notice, setNotice] = useState<string | null>(null);
  const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
  const [form, setForm] = useState<AdminUserFormState | null>(null);
  const [deleteJustification, setDeleteJustification] = useState("");
  const [deleteConfirmStep, setDeleteConfirmStep] = useState<0 | 1 | 2>(0);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const peopleUsers = useMemo(() => users.filter((user) => user.role !== "company"), [users]);
  const filteredUsers = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    return peopleUsers.filter((user) =>
      !normalized ||
      [user.id, user.nombre, user.email, user.displayName, user.headline, user.phone, user.location].join(" ").toLowerCase().includes(normalized),
    );
  }, [peopleUsers, query]);
  const selectedUser = useMemo(
    () => filteredUsers.find((user) => user.id === selectedUserId) ?? peopleUsers.find((user) => user.id === selectedUserId) ?? null,
    [filteredUsers, peopleUsers, selectedUserId],
  );

  return (
    <RoleRouteGuard allowedRole="admin">
      <AdminDashboardShell
        isDark={isDark}
        onToggleTheme={toggleTheme}
        title="Users"
        description="Listado compacto de usuarios con edición completa desde un popup vertical."
        actions={(
          <div className="flex items-center gap-3">
            <p className={isDark ? "text-xs text-slate-400" : "text-xs text-slate-500"}>
              {lastUpdatedAt ? `Actualizado ${new Date(lastUpdatedAt).toLocaleTimeString("es-CO")}` : "Sincronizando"}
            </p>
            <AdminGhostButton isDark={isDark} onClick={refreshUsers}>
              <RefreshCcw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
              Recargar
            </AdminGhostButton>
          </div>
        )}
      >
        {notice ? (
          <div className={isDark ? "rounded-2xl border border-cyan-300/18 bg-cyan-300/8 px-4 py-3 text-sm text-cyan-100" : "rounded-2xl border border-sky-300 bg-sky-50 px-4 py-3 text-sm text-sky-700"}>
            {notice}
          </div>
        ) : null}

        <AdminSurface isDark={isDark}>
          <AdminToolbarInput
            isDark={isDark}
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Buscar por ID, nombre, correo o ubicación"
            className="w-full"
          />
        </AdminSurface>

        <AdminSimpleTable isDark={isDark}>
          <table className="w-full min-w-[760px] text-sm">
            <thead className={isDark ? "border-b border-white/8 bg-white/[0.03] text-slate-400" : "border-b border-slate-200 bg-slate-50 text-slate-500"}>
              <tr>
                <th className="w-14 px-4 py-3 text-left font-medium">Edit</th>
                <th className="px-4 py-3 text-left font-medium">User ID</th>
                <th className="px-4 py-3 text-left font-medium">Email</th>
                <th className="px-4 py-3 text-left font-medium">Plan</th>
              </tr>
            </thead>
            <tbody>
              {filteredUsers.map((user) => (
                <tr key={user.id} className={isDark ? "border-b border-white/6 last:border-b-0" : "border-b border-slate-100 last:border-b-0"}>
                  <td className="px-4 py-4 align-top">
                    <button
                      type="button"
                      onClick={() => {
                        setSelectedUserId(user.id);
                        setForm(createAdminUserFormFromUser(user));
                        setDeleteJustification("");
                        setDeleteConfirmStep(0);
                      }}
                      className={isDark ? "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-slate-100" : "inline-flex h-10 w-10 items-center justify-center rounded-2xl border border-slate-200 bg-slate-50 text-slate-700"}
                      aria-label={`Editar ${user.nombre}`}
                    >
                      <ArrowUpRight className="h-4 w-4" />
                    </button>
                  </td>
                  <td className="px-4 py-4 align-top">
                    <div>
                      <p className={isDark ? "font-medium text-white" : "font-medium text-slate-950"}>{user.id}</p>
                      <p className={isDark ? "mt-1 text-xs text-slate-500" : "mt-1 text-xs text-slate-500"}>{user.nombre}</p>
                    </div>
                  </td>
                  <td className="px-4 py-4 align-top">{user.email}</td>
                  <td className="px-4 py-4 align-top">
                    <AdminPill isDark={isDark}>{user.plan}</AdminPill>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </AdminSimpleTable>

        <TrashedUsersTable
          isDark={isDark}
          trashedUsers={trashedUsers}
          deleting={deleting}
          onRecover={async (trash) => {
            const firstConfirmation = window.confirm(`¿Estás seguro de recuperar a ${trash.displayName}?`);
            if (!firstConfirmation) {
              return;
            }
            const secondConfirmation = window.confirm("Confirma otra vez la recuperación de esta cuenta.");
            if (!secondConfirmation) {
              return;
            }
            setDeleting(true);
            const result = await deleteAdminUser({
              action: "recover",
              trashId: trash.id,
              confirmed: true,
              secondConfirmed: true,
            });
            setDeleting(false);
            setNotice(result === true ? `Usuario recuperado: ${trash.displayName}.` : typeof result === "string" ? result : "No se pudo recuperar el usuario.");
          }}
          onPurge={async (trash) => {
            const firstConfirmation = window.confirm(`¿Estás seguro de eliminar definitivamente a ${trash.displayName}?`);
            if (!firstConfirmation) {
              return;
            }
            const secondConfirmation = window.confirm("Confirma otra vez. Esta eliminación no se puede recuperar.");
            if (!secondConfirmation) {
              return;
            }
            setDeleting(true);
            const result = await deleteAdminUser({
              action: "purge",
              trashId: trash.id,
              confirmed: true,
              secondConfirmed: true,
            });
            setDeleting(false);
            setNotice(result === true ? `Usuario eliminado definitivamente: ${trash.displayName}.` : typeof result === "string" ? result : "No se pudo eliminar definitivamente el usuario.");
          }}
        />

        {selectedUser && form ? (
          <UserEditorModal
            isDark={isDark}
            user={selectedUser}
            form={form}
            deleteJustification={deleteJustification}
            deleteConfirmStep={deleteConfirmStep}
            saving={saving}
            deleting={deleting}
            onClose={() => {
              setSelectedUserId(null);
              setDeleteJustification("");
              setDeleteConfirmStep(0);
            }}
            onFormChange={setForm}
            onDeleteJustificationChange={setDeleteJustification}
            onDeleteConfirmStepChange={setDeleteConfirmStep}
            onSave={async () => {
              setSaving(true);
              const result = await updateAdminUser(buildUpdatePayload(selectedUser.id, form));
              setSaving(false);
              setNotice(result === true ? `Usuario actualizado: ${getConfirmationName(selectedUser)}.` : typeof result === "string" ? result : "No se pudo actualizar el usuario.");
              if (result === true) {
                setSelectedUserId(null);
              }
            }}
            onDelete={async () => {
              setDeleting(true);
              const result = await deleteAdminUser({
                action: "trash",
                userId: selectedUser.id,
                justification: deleteJustification.trim(),
                confirmed: true,
                secondConfirmed: true,
              });
              setDeleting(false);
              setNotice(result === true ? `Usuario enviado a papelera: ${getConfirmationName(selectedUser)}.` : typeof result === "string" ? result : "No se pudo enviar el usuario a papelera.");
              if (result === true) {
                setSelectedUserId(null);
                setDeleteJustification("");
                setDeleteConfirmStep(0);
              }
            }}
          />
        ) : null}
      </AdminDashboardShell>
    </RoleRouteGuard>
  );
}
